const Numeros: C = ({ t, h }) => <Stage t={t} h={h} mode="ring">{(tt) => <AbsoluteFill><Svg><Defs /><Num tt={tt} x={230} y={210} n={5} />{[0, 1, 2].map((i) => <g key={i}><Wire x1={200} x2={1500} y={360 + i * 180} col={["#30363c", "#30363c", "#30363c"][i]} th={46} bare={60} /><Tag x={1000} y={360 + i * 180} tx={String(i + 1)} s={1.4 * P(tt, 0.5 + i * 0.6)} rot={-4 + i * 4} w={110} /></g>)}<Check x={1700} y={540} ok s={2 * P(tt, 2.8)} /></Svg><Lbl tt={tt} at={3.2} x={960} y={950} tx="NO HAY FORMA DE EQUIVOCARTE" bg={GRN} /></AbsoluteFill>}</Stage>;
