const NoMiente: C = ({ t, h }) => <Stage t={t} h={h} mode="iris">{(tt) => <AbsoluteFill><Svg><Defs /><Clamp x={1380} y={480} s={1.4 * P(tt, 0.4)} val="9.0" /></Svg><Lbl tt={tt} at={1} x={620} y={420} tx="«LA PINZA NO MIENTE»" bg={AMB} hand size={60} /><Lbl tt={tt} at={2.6} x={620} y={640} tx="«EL QUE MIENTE ES EL QUE LA PONE MAL»" bg={INK} hand size={34} /></AbsoluteFill>}</Stage>;
const Sab1: C = ({ t, h }) => <Stage t={t} h={h} mode="wipe">{(tt) => <AbsoluteFill><Svg><Defs /><g transform="translate(960,540) rotate(-2)" opacity={cl(P(tt, 0.2) * 2)}><rect x={-520} y={-380} width={1040} height={760} fill="#fbf6e2" stroke="#b9b2a0" strokeWidth={5} /><T x={0} y={-290} tx="SÁBADO · 1) CON LA CASA ANDANDO" size={46} hand />{[["Comedor: con tierra", 1], ["Dormitorio: SIN tierra", 0], ["Cocina = térmica 2", 1], ["Baño = térmica 3", 1]].map(([n, o], i) => <g key={i} opacity={W(tt, 0.9 + i * 0.6, 1.2 + i * 0.6)}><T x={-420} y={-160 + i * 130} tx={n as string} size={60} hand anchor="start" /><Check x={440} y={-180 + i * 130} ok={!!o} s={0.9} /></g>)}</g></Svg></AbsoluteFill>}</Stage>;
const Sab2: C = ({ t, h }) => <Stage t={t} h={h} mode="split">{(tt) => <AbsoluteFill><Svg><Defs />{[["DISYUNTOR: T", "SALTA", 0.3], ["TAPA DEL TABLERO", "FRÍA", 1.2], ["FICHAS GRANDES", "ANOTAR LAS CALIENTES", 2.1]].map(([a, b, at], i) => <Card key={i} x={960} y={240 + i * 240} w={1320} h={200} s={P(tt, at as number)} bg={i === 2 ? AMB : INK}><T x={-620} y={22} tx={`${i + 1}`} size={100} anchor="start" col={RED} /><T x={-520} y={-4} tx={a as string} size={54} anchor="start" /><T x={-520} y={62} tx={b as string} size={40} anchor="start" col="#3f5166" /></Card>)}</Svg></AbsoluteFill>}</Stage>;
const Sab3: C = ({ t, h }) => <Stage t={t} h={h} mode="diag">{(tt) => { const st = ["GENERAL ABAJO", "CINTA", "VINCHA", "BUSCAPOLO", "FOTO", "NÚMEROS", "PELADO", "BORNES", "TIRÓN", "ACORDEÓN", "SUBIR DE A UNA"]; return <AbsoluteFill><Svg><Defs />{st.map((n, i) => { const x = 300 + (i % 4) * 440, y = 260 + Math.floor(i / 4) * 230; const s = P(tt, 0.2 + i * 0.33, 9); return <Card key={i} x={x} y={y} w={400} h={180} s={s} bg={i === 10 ? GRN : i === 0 ? AMB : INK}><T x={0} y={18} tx={n} size={n.length > 11 ? 36 : 46} /></Card>; })}</Svg></AbsoluteFill>; }}</Stage>;
const Sab4: C = ({ t, h }) => <Stage t={t} h={h} mode="ring">{(tt) => { const k = W(tt, 1.2, 3); return <AbsoluteFill><Svg><Defs /><Bar x={260} y={260} w={1400} h={120} k={1 - 0.5 * k} col={k > 0.9 ? GRN : RED} tx={k > 0.9 ? "LA MITAD DE TIEMPO" : "LO QUE TARDA"} /><Bar x={260} y={480} w={1400} h={120} k={1 - 0.5 * k} col={k > 0.9 ? GRN : RED} tx={k > 0.9 ? "LA MITAD DE PLATA" : "LO QUE COBRA"} /></Svg><Lbl tt={tt} at={3} x={960} y={780} tx="EL DIAGNÓSTICO SE LO HICISTE VOS" bg={AMB} /></AbsoluteFill>; }}</Stage>;
const Caja: C = ({ t, h }) => { const it = ["BUSCAPOLO", "MULTÍMETRO", "PELADORA", "2 AISLADOS 1000 V", "PINZA COMÚN", "PINZA DE PUNTA", "CINTA AISLADORA", "BORNES DE PALANCA", "CINTA Y BIROME", "LINTERNA DE VINCHA"]; return <Stage t={t} h={h} mode="drop">{(tt) => <AbsoluteFill><Svg><Defs /><rect x={210} y={190} width={1500} height={760} rx={24} fill="#7a3620" stroke="#3f1a0c" strokeWidth={10} /><rect x={240} y={220} width={1440} height={700} rx={14} fill="#2a2018" />{it.map((n, i) => <Card key={i} x={590 + (i % 2) * 740} y={300 + Math.floor(i / 2) * 136} w={690} h={110} s={P(tt, 0.2 + i * 0.36, 9)} bg={INK} rot={i % 2 ? 3 : -3}><T x={0} y={16} tx={n} size={42} /></Card>)}</Svg><Lbl tt={tt} at={3.9} x={960} y={1010} tx="EL 90% DE LO QUE SE HACE EN UNA CASA" bg={AMB} size={36} /></AbsoluteFill>}</Stage>; };
const Barata: C = ({ t, h }) => <Stage t={t} h={h} mode="split">{(tt) => { const b = W(tt, 1.2, 2); return <AbsoluteFill><Svg><Defs /><g transform={`translate(560,300) rotate(${b * 18})`}><Screwdriver x={0} y={350} s={1.3} rot={0} /></g><Card x={1320} y={400} w={560} h={190} s={P(tt, 1.8)} bg="#ffe1dc"><T x={0} y={26} tx="1ª COMPRA" size={72} col={RED} /></Card><Card x={1320} y={640} w={560} h={190} s={P(tt, 2.6)} bg="#ffe1dc"><T x={0} y={26} tx="2ª COMPRA" size={72} col={RED} /></Card></Svg><Lbl tt={tt} at={3.4} x={960} y={950} tx="EL BUSCAPOLO: NUNCA EL MÁS BARATO" bg={AMB} /></AbsoluteFill>; }}</Stage>;
const Parar: C = ({ t, h }) => <Stage t={t} h={h} mode="iris">{(tt) => { const k = W(tt, 0.3, 1.6); return <AbsoluteFill><Svg><Defs /><line x1={200} y1={540} x2={1720} y2={540} stroke={INK} strokeWidth={12} opacity={0.5} />{[["MEDIDOR", 360], ["ACOMETIDA", 720]].map(([n, x]) => <Card key={n as string} x={x as number} y={540} w={330} h={170} s={P(tt, 1)} bg="#ffe1dc"><T x={0} y={18} tx={n as string} size={42} col={RED} /></Card>)}<line x1={990} y1={220} x2={990} y2={860} stroke={RED} strokeWidth={16} strokeDasharray={`${k * 700} 700`} /><Card x={1400} y={540} w={640} h={170} s={P(tt, 1.8)} bg={GRN}><T x={0} y={18} tx="DESPUÉS DE LA GENERAL" size={44} /></Card></Svg><Big tt={tt} at={3} x={960} y={900} tx="TRUCO 31" size={120} /></AbsoluteFill>; }}</Stage>;
const SinContacto: C = ({ t, h }) => <Stage t={t} h={h} mode="diag">{(tt) => <AbsoluteFill><Svg><Defs /><Card x={560} y={500} w={680} h={600} s={P(tt, 0.3)}><Tester x={-40} y={200} lit={1} rot={0} /><T x={80} y={-70} tx="PRIMER AVISO" size={38} /><Check x={230} y={40} ok s={1} /></Card><Card x={1360} y={500} w={680} h={600} s={P(tt, 1.4)} bg="#e6f6ee"><Meter x={0} y={-40} val="0.0" s={0.8} /><T x={0} y={246} tx="PARA TOCAR: CONTACTO" size={36} /></Card></Svg><Lbl tt={tt} at={3.2} x={960} y={950} tx="YO CONFIRMO CON LOS DOS" bg={AMB} /></AbsoluteFill>}</Stage>;
const Solo: C = ({ t, h }) => <Stage t={t} h={h} mode="split">{(tt) => <AbsoluteFill><Svg><Defs />{[["CAMBIAR UN TOMA", true], ["CAMBIAR UNA LLAVE", true]].map(([n, o], i) => <Pill key={i} tt={tt} at={0.4 + i * 0.6} x={520} y={380 + i * 190} w={720} tx={n as string} ok={o as boolean} />)}{["CIRCUITOS NUEVOS", "TABLERO PRINCIPAL", "CAMBIAR TÉRMICAS"].map((n, i) => <Pill key={i} tt={tt} at={1.8 + i * 0.6} x={1400} y={290 + i * 190} w={720} tx={n} ok={false} />)}</Svg><Lbl tt={tt} at={3.6} x={1400} y={900} tx="MATRICULADO" bg={AMB} /><Lbl tt={tt} at={1.4} x={520} y={720} tx="TÉRMICA ABAJO + BUSCAPOLO" bg={GRN} size={36} /></AbsoluteFill>}</Stage>;
const Calendario: C = ({ t, h }) => <Stage t={t} h={h} mode="blinds">{(tt) => <AbsoluteFill><Svg><Defs />{[["1 VEZ POR MES", "BOTÓN DEL DISYUNTOR", 12, AMB], ["1 VEZ POR AÑO", "PROBADOR · FICHAS · TAPA", 1, GRN]].map(([a, b, n, c], i) => { const s = P(tt, 0.3 + i * 1.3); return <g key={i} opacity={cl(s * 2)}><T x={260} y={250 + i * 300} tx={a as string} size={68} anchor="start" col={c as string} /><T x={260} y={320 + i * 300} tx={b as string} size={44} anchor="start" col={INK} />{Array.from({ length: n as number }, (_, j) => <rect key={j} x={1040 + (i === 0 ? j * 58 : 0)} y={210 + i * 300} width={46} height={100} rx={8} fill={c as string} opacity={W(tt, 0.6 + i * 1.3 + j * 0.08, 0.8 + i * 1.3 + j * 0.08)} />)}</g>; })}</Svg><Lbl tt={tt} at={3.2} x={960} y={890} tx="CASA DE +30 AÑOS SIN REVISAR: UN MATRICULADO" bg={INK} size={36} /></AbsoluteFill>}</Stage>;
const Palanca: C = ({ t, h }) => <Stage t={t} h={h} mode="ring">{(tt) => { const k = W(tt, 0.6, 2); return <AbsoluteFill><Svg><Defs /><rect x={940} y={330} width={520} height={400} rx={30} fill="rgba(240,245,250,.25)" stroke={INK} strokeWidth={6} /><rect x={1040} y={lp(240, 310, k)} width={150} height={90} rx={14} fill="#ff8a1e" /><Wire x1={200} x2={lp(760, 1100, W(tt, 1.2, 2.4))} y={560} col={BRN} th={56} bare={120} /><line x1={1320} y1={480} x2={1320} y2={640} stroke={GRN} strokeWidth={10} strokeDasharray="14 10" opacity={W(tt, 2.5, 3)} /></Svg><Lbl tt={tt} at={2.6} x={1260} y={820} tx="COBRE HASTA EL FONDO" bg={GRN} /><Lbl tt={tt} at={3.4} x={540} y={820} tx="Y TIRÓN DE PRUEBA" bg={AMB} /><Lbl tt={tt} at={0.5} x={540} y={250} tx="SIEMPRE DENTRO DE CAJA CON TAPA" bg={INK} size={34} /></AbsoluteFill>; }}</Stage>;
const Cat: C = ({ t, h }) => <Stage t={t} h={h} mode="drop">{(tt) => <AbsoluteFill><Svg><Defs /><Meter x={640} y={540} val="229" s={1.9} /></Svg><Lbl tt={tt} at={1} x={1380} y={280} tx="CATEGORÍA IMPRESA" bg={AMB} /><Lbl tt={tt} at={1.8} x={1380} y={450} tx="PUNTAS CON PROTECTOR" bg={INK} /><Lbl tt={tt} at={2.6} x={1380} y={620} tx="CON CONTINUIDAD" bg={INK} /><Lbl tt={tt} at={3.5} x={1380} y={800} tx="NO UN JUGUETE" bg={RED} col={INK} /></AbsoluteFill>}</Stage>;
const Err: (n: number, tit: string, sub: string, draw: (tt: number) => React.ReactNode, mode: "iris" | "split" | "ring") => C = (n, tit, sub, draw, mode) => ({ t, h }) => <Stage t={t} h={h} mode={mode}>{(tt) => <AbsoluteFill><Svg><Defs />{draw(tt)}<g transform={`translate(1660,250) scale(${2.6 * P(tt, 0.3)})`}><circle r={46} fill={RED} /><path d="M -22 -22 l 44 44 M 22 -22 l -44 44" stroke="#fff" strokeWidth={12} strokeLinecap="round" /></g></Svg><Big tt={tt} at={0.5} x={260} y={210} tx={String(n)} size={210} col={RED} /><Lbl tt={tt} at={1.6} x={960} y={850} tx={tit} bg={RED} col={INK} /><Lbl tt={tt} at={2.8} x={960} y={980} tx={sub} bg={INK} /></AbsoluteFill>}</Stage>;
const E1 = Err(1, "SUBIR LA TÉRMICA", "EL CABLE CALIENTA Y ELLA NO SE ENTERA", (tt) => <g><Breaker x={600} y={420} s={1} on={1} amp="C32" /><Cable x1={700} x2={1400} y={440} mm="1,5" th={50} hot={W(tt, 1, 2.4)} /></g>, "iris");
const E2 = Err(2, "PUENTEAR O SACAR LA TIERRA", "SE BUSCA LA FUGA · SI NO, MATRICULADO", (tt) => <g><Socket x={760} y={430} s={1} /><path d={`M 660 620 Q 980 ${760 + 30 * Math.sin(tt * 4)} 1280 520`} stroke="url(#vy)" strokeWidth={36} fill="none" /><line x1={980} y1={560} x2={980} y2={760} stroke={RED} strokeWidth={14} /></g>, "split");
const E3 = Err(3, "TRABAJAR CON TENSIÓN", "«EL QUE DICE QUE SABE, NO SABE»", (tt) => <g><Wire x1={420} x2={1200} y={440} col={BRN} th={56} bare={70} /><Spark x={1290} y={440} k={0.7 + 0.3 * Math.sin(tt * 18)} /></g>, "ring");

